import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import ContentsList from "./ContentsList.js";

/** Two sections, in the order a page passes them. */
const SECTIONS = [
  { id: "usage", title: "Usage" },
  { id: "changes", title: "Changes" },
] as const;

describe("ContentsList", () => {
  it("links to every section by its fragment, in order", () => {
    render(<ContentsList sections={SECTIONS} />);
    const links = screen.getAllByRole("link");
    expect(
      links.map((link) => [link.textContent, link.getAttribute("href")]),
    ).toEqual([
      ["Usage", "#usage"],
      ["Changes", "#changes"],
    ]);
    expect(screen.getByRole("list").tagName).toBe("OL");
  });

  it("marks the current section's link, and only that one", () => {
    render(<ContentsList current="changes" sections={SECTIONS} />);
    expect(
      screen
        .getByRole("link", { name: "Changes" })
        .getAttribute("aria-current"),
    ).toBe("location");
    expect(
      screen.getByRole("link", { name: "Usage" }).hasAttribute("aria-current"),
    ).toBe(false);
  });

  it("merges a consumer className after its own and passes native props", () => {
    render(
      <ContentsList aria-label="Sections" className="list" sections={[]} />,
    );
    expect(screen.getByLabelText("Sections").className).toBe(
      "ds contents-list list",
    );
  });
});
